// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // 1. fund the contract with 10 ether
        vm.deal(address(c), 10 ether);
        // 2. prank as owner and call withdrawAll to a recipient
        address recipient = address(0x1234);
        vm.prank(address(this));
        c.withdrawAll(recipient);
        // 3. after withdrawal, the reference contract should have 0 balance, buggy keeps 10 ether
        assertEq(address(c).balance, 0);
    }
}
